    <h3 ref={heading} tabIndex={-1} className="setup-title">{step === 1 ? 'Give your work a home.' : step === 2 ? 'Start with realistic limits.' : initial ? 'Ready to save your settings.' : 'Choose where to begin.'}</h3>
    {step === 1 && <><p>Name the organization and bench this browser belongs to. You can create another workspace for a different company or site.</p><label className="field-label" htmlFor="company-name">Company or organization name</label><input id="company-name" className="wide-input" value={profile.name} maxLength={100} required placeholder="e.g. Northside Device Reuse" onChange={event => setProfile({ ...profile, name: event.target.value })}/><label className="field-label" htmlFor="company-site">Site or workshop <span className="optional">optional</span></label><input id="company-site" className="wide-input" value={profile.site} maxLength={100} placeholder="e.g. Bengaluru refurbishment bench" onChange={event => setProfile({ ...profile, site: event.target.value })}/><fieldset className="choice-fieldset"><legend>What kind of team is this?</legend><div className="choice-grid">{(Object.keys(companyTypes) as CompanyProfile['type'][]).map(type => <label key={type} className={`choice-card ${profile.type === type ? 'chosen' : ''}`}><input type="radio" name="company-type" checked={profile.type === type} onChange={() => setProfile({ ...profile, type })}/><strong>{companyTypes[type]}</strong><small>{type === 'refurbisher' ? 'Recover devices and manage scarce parts.' : type === 'school' ? 'Put existing equipment back in service.' : 'Prepare donated computers for reuse.'}</small></label>)}</div></fieldset></>}
    {step === 2 && <><p>These defaults apply to new batches. Each batch keeps its own limits, and existing batches stay unchanged.</p><div className="setup-limits"><label className="field-label">Technician minutes per batch<input type="number" min={0} max={10000} step={1} required value={profile.defaultTechnicianMinutes} onChange={event => setProfile({ ...profile, defaultTechnicianMinutes: Number(event.target.value) })}/><small>Total available bench time, including part preparation.</small></label><label className="field-label">Parts budget per batch (USD)<input type="number" min={0} max={10000} step="0.01" required value={profile.defaultBudgetCents / 100} onChange={event => setProfile({ ...profile, defaultBudgetCents: Math.round(Number(event.target.value) * 100) })}/><small>Incremental component spend. Zero is a valid budget.</small></label></div><div className="setup-note"><ShieldCheck size={20}/><p>Each proposal still needs verified compatibility, completed repairs, sanitization, and final QA.</p></div></>}
